	const maxAddrLen = 4096
	addrInput := key
	if len(addrInput) > maxAddrLen {
		addrInput = addrInput[:maxAddrLen]
	}
	remaining := strings.TrimSpace(addrInput)
	addr := Address{Original: remaining}
	if strings.Contains(remaining, "://") {
		schemeParts := strings.SplitN(remaining, "://", 2)
		addr.Scheme = schemeParts[0]
		remaining = schemeParts[1]
	}

